-- 18 Platinum-tier deep-dive surveys ($18–$20 reward), all content categories, 50 questions each.
-- Thoughtful scenario + reflection mix (not generic Likert grids). Idempotent on slug.
--
-- Requires public.surveys (20260325_surveys_and_completions), payment_categories + platinum row,
-- and survey_category / payment_category_id columns (see 20260327, 20260328). Apply the full
-- migration chain (e.g. supabase db push); do not run this file alone on an empty database.

insert into public.surveys (slug, title, description, reward_cents, estimated_minutes, questions, is_active, survey_category, payment_category_id)
select
  'platinum-tech-ai-ethics-judgment',
  'Judgment in the Age of Intelligent Systems',
  'Reflect on how AI shapes decisions at work and home—where you trust it, where you resist, and what you owe others when machines recommend.',
  1800,
  48,
  $json$[{"id": "platinumtechaiethicsjudg_01", "type": "choice", "label": "When you think about this topic in your own life, how often does it feel emotionally ‘loaded’ rather than neutral?", "options": ["Almost always", "Often", "Sometimes", "Rarely", "Almost never"]}, {"id": "platinumtechaiethicsjudg_02", "type": "choice", "label": "How much do your answers here depend on your current life stage (care, dependents, income, health)?", "options": ["A great deal", "Quite a bit", "Somewhat", "A little", "Hardly at all"]}, {"id": "platinumtechaiethicsjudg_03", "type": "choice", "label": "Do you usually seek out disagreement on this topic, or prefer communities that largely agree with you?", "options": ["Seek disagreement", "Mix of both", "Prefer agreement", "Avoid the topic", "Not sure"]}, {"id": "platinumtechaiethicsjudg_04", "type": "choice", "label": "Which best describes your relationship to ‘expert’ voices on this topic?", "options": ["I defer to them", "I weigh them against experience", "I’m skeptical by default", "I ignore them", "It varies wildly"]}, {"id": "platinumtechaiethicsjudg_05", "type": "choice", "label": "If you had to choose, is this topic more about individual choices or systems and institutions?", "options": ["Mostly individual", "Lean individual", "Even split", "Lean systems", "Mostly systems"]}, {"id": "platinumtechaiethicsjudg_06", "type": "choice", "label": "How comfortable are you admitting uncertainty or changing your mind publicly about this?", "options": ["Very comfortable", "Somewhat", "Neutral", "Uncomfortable", "I avoid it"]}, {"id": "platinumtechaiethicsjudg_07", "type": "choice", "label": "When resources are scarce (time, money, attention), how do you usually decide what to protect first?", "options": ["Family or close ties", "Health or rest", "Work or income", "Principles or causes", "Something else"]}, {"id": "platinumtechaiethicsjudg_08", "type": "choice", "label": "How much does fear of being judged shape what you say about this topic in ordinary conversation?", "options": ["A great deal", "Quite a bit", "Somewhat", "A little", "Not much"]}, {"id": "platinumtechaiethicsjudg_09", "type": "text", "label": "Describe a recent moment when this topic forced you to choose between two values you both care about. What did you pick, and what did it cost?"}, {"id": "platinumtechaiethicsjudg_10", "type": "text", "label": "What is one widely repeated opinion about this topic that you think is too simple? What nuance is usually missing?"}, {"id": "platinumtechaiethicsjudg_11", "type": "text", "label": "If someone you respect disagreed with you on this, what is the strongest version of their argument you could offer on their behalf?"}, {"id": "platinumtechaiethicsjudg_12", "type": "text", "label": "What would ‘good enough’ look like for you on this topic in the next year—not perfection, but meaningful progress?"}, {"id": "platinumtechaiethicsjudg_13", "type": "text", "label": "Who benefits most from the status quo in this area, and who pays the highest hidden costs? Answer in your own words."}, {"id": "platinumtechaiethicsjudg_14", "type": "text", "label": "What question are you still genuinely unsure about—and why haven’t you resolved it yet?"}, {"id": "platinumtechaiethicsjudg_15", "type": "choice", "label": "You can improve one thing in this domain with serious effort, or help three people in a smaller way. Which pulls you?", "options": ["The deep single improvement", "The broader smaller help", "I’d try to combine", "Refuse the frame", "Depends on who is affected"]}, {"id": "platinumtechaiethicsjudg_16", "type": "choice", "label": "A policy change would help many strangers but slightly inconvenience you weekly. Support it?", "options": ["Yes, strongly", "Yes, cautiously", "Need more detail", "Probably not", "No"]}, {"id": "platinumtechaiethicsjudg_17", "type": "choice", "label": "You discover a habit of yours has unintended harm you didn’t see before. What’s your first instinct?", "options": ["Change quickly", "Research more", "Feel guilty", "Rationalize", "Talk to someone"]}, {"id": "platinumtechaiethicsjudg_18", "type": "choice", "label": "How much do you weigh future people (you’ll never meet) in decisions that affect this topic today?", "options": ["A lot", "Some", "Unsure how to", "Rarely", "Not consciously"]}, {"id": "platinumtechaiethicsjudg_19", "type": "choice", "label": "When brands or leaders speak on this topic, what erodes your trust fastest?", "options": ["Vague virtue signaling", "Data overreach", "Hypocrisy", "Fear messaging", "Overpromising"]}, {"id": "platinumtechaiethicsjudg_20", "type": "choice", "label": "If you could only protect one—honesty, kindness, or effectiveness—which do you lean on when they conflict here?", "options": ["Honesty", "Kindness", "Effectiveness", "Refuse to rank", "Situational blend"]}, {"id": "platinumtechaiethicsjudg_21", "type": "choice", "label": "Do you experience this topic more as a private inner struggle or a public political fight?", "options": ["Mostly private", "More private", "Both equally", "More public", "Mostly public"]}, {"id": "platinumtechaiethicsjudg_22", "type": "choice", "label": "How often do you update your views based on new evidence vs. doubling down?", "options": ["Update often", "Sometimes update", "Slow to update", "Rarely update", "Depends on the source"]}, {"id": "platinumtechaiethicsjudg_23", "type": "choice", "label": "Which risk worries you more in this area: being exploited, or missing an opportunity to help?", "options": ["Being exploited", "Missing help", "Both equally", "Neither—different fears", "Not sure"]}, {"id": "platinumtechaiethicsjudg_24", "type": "choice", "label": "When you feel powerless here, what do you usually do with that feeling?", "options": ["Channel it into action", "Numb or distract", "Talk it through", "Blame systems", "Sit with it quietly"]}, {"id": "platinumtechaiethicsjudg_25", "type": "choice", "label": "Would you rather be remembered as principled or pragmatic on this topic?", "options": ["Principled", "Pragmatic", "Both—contextual", "Neither matters to me", "I don’t think in those terms"]}, {"id": "platinumtechaiethicsjudg_26", "type": "choice", "label": "How much does your answer depend on where you live (country, city, infrastructure)?", "options": ["Completely", "Quite a bit", "Moderately", "Somewhat", "Hardly"]}, {"id": "platinumtechaiethicsjudg_27", "type": "choice", "label": "If your 18-year-old self disagreed with your current view, who would you listen to harder?", "options": ["Younger self (idealism)", "Current self (experience)", "Neither—merge the tension", "I can’t imagine", "Depends on the issue"]}, {"id": "platinumtechaiethicsjudg_28", "type": "choice", "label": "When you see others suffer in this domain, how often do you feel complicit in systems you participate in?", "options": ["Often", "Sometimes", "Rarely", "I reject guilt framing", "I oscillate"]}, {"id": "platinumtechaiethicsjudg_29", "type": "choice", "label": "Pick the tension that feels most alive for you right now:", "options": ["Freedom vs. safety", "Speed vs. care", "Truth vs. harmony", "Growth vs. limits", "Individual vs. collective"]}, {"id": "platinumtechaiethicsjudg_30", "type": "choice", "label": "How do you react when someone uses moral language (‘you should’) about this topic?", "options": ["Open if empathetic", "Defensive", "Curious about their story", "Dismissive if preachy", "Depends who says it"]}, {"id": "platinumtechaiethicsjudg_31", "type": "choice", "label": "If you had to teach a 20-minute class on this topic, what would you refuse to oversimplify?", "options": ["Causes", "Tradeoffs", "Who is hurt", "Solutions", "History"]}, {"id": "platinumtechaiethicsjudg_32", "type": "choice", "label": "Which lens do you trust least when people analyze this topic?", "options": ["Pure economics", "Pure morality", "Pure tech optimism", "Pure nostalgia", "Pure outrage"]}, {"id": "platinumtechaiethicsjudg_33", "type": "text", "label": "Name one assumption people make about ‘people like you’ in this topic that is often wrong or incomplete."}, {"id": "platinumtechaiethicsjudg_34", "type": "text", "label": "What is a constructive disagreement you wish more people could have about this—without collapsing into teams?"}, {"id": "platinumtechaiethicsjudg_35", "type": "text", "label": "If you could ask one question to the most powerful decision-maker in this space, what would it be—and why?"}, {"id": "platinumtechaiethicsjudg_36", "type": "text", "label": "What would you want researchers to measure that they rarely measure today?"}, {"id": "platinumtechaiethicsjudg_37", "type": "text", "label": "Describe a time you changed your behavior here—not because you were shamed, but because something clicked."}, {"id": "platinumtechaiethicsjudg_38", "type": "text", "label": "What is one thing you wish institutions (employers, schools, governments) understood about everyday lived experience here?"}, {"id": "platinumtechaiethicsjudg_39", "type": "choice", "label": "After reflecting, how clear is your own position on this topic?", "options": ["Very clear", "Somewhat clear", "Mixed", "Uncertain", "Intentionally open"]}, {"id": "platinumtechaiethicsjudg_40", "type": "choice", "label": "Would you want a close friend to challenge you on this more often, less often, or about the same?", "options": ["More often", "About the same", "Less often", "Depends on how they do it", "Not sure"]}, {"id": "platinumtechaiethicsjudg_41", "type": "choice", "label": "How likely are you to seek new information on this in the next month?", "options": ["Very likely", "Likely", "Maybe", "Unlikely", "Very unlikely"]}, {"id": "platinumtechaiethicsjudg_42", "type": "choice", "label": "Do you feel more hopeful, more concerned, or about the same compared to a year ago?", "options": ["More hopeful", "About the same", "More concerned", "Both hopeful and concerned", "I avoid comparing"]}, {"id": "platinumtechaiethicsjudg_43", "type": "choice", "label": "If you could fund one type of project in this area, what would you pick?", "options": ["Education", "Infrastructure", "Research", "Direct aid", "Advocacy"]}, {"id": "platinumtechaiethicsjudg_44", "type": "choice", "label": "How much does community (online or offline) matter for how you think about this topic?", "options": ["Essential", "Important", "Moderate", "Minor", "I think alone"]}, {"id": "platinumtechaiethicsjudg_45", "type": "choice", "label": "Would you rather improve your own situation first, or work on collective change first?", "options": ["Own situation", "Collective change", "Both in parallel", "Refuse the split", "Context-dependent"]}, {"id": "platinumtechaiethicsjudg_46", "type": "choice", "label": "How often do you translate reflection into concrete next steps?", "options": ["Often", "Sometimes", "Rarely", "I resist planning", "I over-plan"]}, {"id": "platinumtechaiethicsjudg_47", "type": "choice", "label": "What would make you disengage entirely from caring about this topic?", "options": ["Burnout", "Cynicism", "Competing priorities", "I can’t imagine", "Already happened sometimes"]}, {"id": "platinumtechaiethicsjudg_48", "type": "choice", "label": "How much do you want decision-makers to read honest, nuanced survey answers like yours?", "options": ["A lot—please share themes", "Some—aggregate only", "Little—privacy first", "Unsure", "No—too risky"]}, {"id": "platinumtechaiethicsjudg_49", "type": "choice", "label": "Does thinking this through leave you with more compassion, more urgency, or more ambivalence?", "options": ["More compassion", "More urgency", "More ambivalence", "Mix of all three", "Something else"]}, {"id": "platinumtechaiethicsjudg_50", "type": "choice", "label": "Final calibration: how representative do you think your answers are of people in situations very different from yours?", "options": ["Very representative", "Somewhat", "Not very", "I doubt it", "I actively don’t know"]}]$json$::jsonb,
  true,
  'Technology',
  pc.id
from public.payment_categories pc
where pc.slug = 'platinum'
limit 1
on conflict (slug) do nothing;

